/* Skin "supabase" (Supabase): the tweakcn preset "supabase" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="supabase" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: Outfit (Google Fonts, loaded when the skin is on). */
[data-skin="supabase"] {
  --background: hsl(0 0% 99%);
  --foreground: hsl(0 0% 9%);
  --card: hsl(0 0% 99%);
  --card-foreground: hsl(0 0% 9%);
  --popover: hsl(0 0% 99%);
  --popover-foreground: hsl(0 0% 32%);
  --primary: hsl(151 67% 67%);
  --primary-foreground: hsl(153.3 13% 13.5%);
  --secondary: hsl(0 0% 99%);
  --secondary-foreground: hsl(0 0% 9%);
  --muted: hsl(0 0% 93%);
  --muted-foreground: hsl(0 0% 12.5%);
  --accent: hsl(0 0% 93%);
  --accent-foreground: hsl(0 0% 12.5%);
  --destructive: hsl(9.9 82% 43.5%);
  --destructive-foreground: hsl(0 100% 99.4%);
  --border: hsl(0 0% 87%);
  --input: hsl(0 0% 96%);
  --ring: hsl(151 67% 67%);
  --chart-1: hsl(151 67% 67%);
  --chart-2: hsl(217.2 91.2% 59.8%);
  --chart-3: hsl(258.3 89.5% 66.3%);
  --chart-4: hsl(37.7 92.1% 50.2%);
  --chart-5: hsl(160.1 84.1% 39.4%);
  --sidebar: hsl(0 0% 99%);
  --sidebar-foreground: hsl(0 0% 44%);
  --sidebar-primary: hsl(151 67% 67%);
  --sidebar-primary-foreground: hsl(153.3 13% 13.5%);
  --sidebar-accent: hsl(0 0% 93%);
  --sidebar-accent-foreground: hsl(0 0% 12.5%);
  --sidebar-border: hsl(0 0% 87%);
  --sidebar-ring: hsl(151 67% 67%);
  --font-sans: Outfit, sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: monospace;
  --radius: 0.5rem;
  --shadow-2xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.09);
  --shadow-xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.09);
  --shadow-sm: 0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 1px 2px -1px hsl(0 0% 0% / 0.17);
  --shadow: 0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 1px 2px -1px hsl(0 0% 0% / 0.17);
  --shadow-md: 0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 2px 4px -1px hsl(0 0% 0% / 0.17);
  --shadow-lg: 0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 4px 6px -1px hsl(0 0% 0% / 0.17);
  --shadow-xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 8px 10px -1px hsl(0 0% 0% / 0.17);
  --shadow-2xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.43);
  --tracking-normal: 0.025em;
  --tracking-tighter: calc(var(--tracking-normal) - 0.05em);
  --tracking-tight: calc(var(--tracking-normal) - 0.025em);
  --tracking-wide: calc(var(--tracking-normal) + 0.025em);
  --tracking-wider: calc(var(--tracking-normal) + 0.05em);
  --tracking-widest: calc(var(--tracking-normal) + 0.1em);
  --destructive-hover: hsl(9.9 82% 37.5%);
}

:is(.dark, [data-theme="dark"]) [data-skin="supabase"],
[data-skin="supabase"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(0 0% 7%);
  --foreground: hsl(214 32% 91%);
  --card: hsl(0 0% 9%);
  --card-foreground: hsl(214 32% 91%);
  --popover: hsl(0 0% 14%);
  --popover-foreground: hsl(0 0% 66%);
  --primary: hsl(154.9 100% 19.2%);
  --primary-foreground: hsl(153 19% 89%);
  --secondary: hsl(0 0% 14%);
  --secondary-foreground: hsl(0 0% 98%);
  --muted: hsl(0 0% 12%);
  --muted-foreground: hsl(0 0% 64%);
  --accent: hsl(0 0% 19%);
  --accent-foreground: hsl(0 0% 98%);
  --destructive: hsl(6.7 60% 20.6%);
  --destructive-foreground: hsl(12 12% 92%);
  --border: hsl(0 0% 16%);
  --input: hsl(0 0% 14%);
  --ring: hsl(142 69% 58%);
  --chart-1: hsl(142 69% 58%);
  --chart-2: hsl(213 94% 68%);
  --chart-3: hsl(255.1 91.7% 76.3%);
  --chart-4: hsl(43.3 96.4% 56.3%);
  --chart-5: hsl(172.5 66% 50.4%);
  --sidebar: hsl(0 0% 7%);
  --sidebar-foreground: hsl(0 0% 54%);
  --sidebar-primary: hsl(154.9 100% 19.2%);
  --sidebar-primary-foreground: hsl(153 19% 89%);
  --sidebar-accent: hsl(0 0% 19%);
  --sidebar-accent-foreground: hsl(0 0% 98%);
  --sidebar-border: hsl(0 0% 16%);
  --sidebar-ring: hsl(142 69% 58%);
  --shadow-2xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.09);
  --shadow-xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.09);
  --shadow-sm: 0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 1px 2px -1px hsl(0 0% 0% / 0.17);
  --shadow: 0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 1px 2px -1px hsl(0 0% 0% / 0.17);
  --shadow-md: 0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 2px 4px -1px hsl(0 0% 0% / 0.17);
  --shadow-lg: 0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 4px 6px -1px hsl(0 0% 0% / 0.17);
  --shadow-xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.17), 0px 8px 10px -1px hsl(0 0% 0% / 0.17);
  --shadow-2xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.43);
  --destructive-hover: hsl(6.7 60% 14.6%);
}

:root[data-skin="supabase"] body { letter-spacing: var(--tracking-normal); }
[data-skin="supabase"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="supabase"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="supabase"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="supabase"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="supabase"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="supabase"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
